/**
 * libZFork2 — Soundbank V1 Demo
 *
 * Demonstrates:
 *   - Loading a text soundbank (API V1)
 *   - Diagnosing load failures with EntryCount / SkippedCount
 *   - Dynamically enumerating whatever events are actually in the loaded
 *     bank (zfork2_GetBankEventName) and building the menu from that —
 *     works with ANY bank, including one generated by zfork2_bank_builder
 *     with arbitrary event ids, not just the hand-authored sample bank.
 *   - Group override playback
 *   - Bank-driven group effects (@echo / @reverb directives)
 *
 * Usage:
 *   zfork2_soundbank_v1 [bank_file]
 *
 * Default bank:
 *   examples/samples/soundbank_v1.txt  (relative to the executable or repo root)
 *
 * Bank file format (semicolon-separated, one entry per line):
 *   eventId;pfad;gruppe;typ;lautstaerke;pan;prioritaet;loop
 *   typ: predecoded | streaming
 *
 * WICHTIG: Pfade in der Bank-Datei sind RELATIV ZUM VERZEICHNIS DER BANK-DATEI,
 *          nicht zum Arbeitsverzeichnis des Programms!
 *
 * Binaere Bank (V1):
 *   Bevorzugt wird direkt "soundbank_v1.bank" (binaeres "ZFBK"-Format)
 *   geladen -- kein Parsen/Kompilieren bei jedem Start. Existiert nur die
 *   Text-Datei (oder ist sie neuer als das .bank), wird einmalig mit
 *   zfork2_CompileBankV1() kompiliert; jeder weitere Start laedt dann
 *   wieder direkt binaer. zfork2_LoadBankV1() erkennt beide Formate
 *   automatisch.
 *
 * Sounds in die .bank einbetten (self-contained, keine sounds/-Ordner-Abhaengigkeit):
 *   zfork2_CompileBankV1Embedded() liest zusaetzlich jede referenzierte
 *   Sound-Datei von der Platte und packt ihre Rohbytes direkt in die .bank
 *   (binaeres Format v3). Das fertige .bank braucht dann keine externen
 *   Dateien mehr -- zum Ausliefern reicht die eine Datei. Bleibt bewusst
 *   nativ in SoundBankV1 (kein Cross-Projekt-Link auf ein separates
 *   Archiv-Format): einfacherer Build, kein zusaetzliches Abhaengigkeits-
 *   Geflecht. Diese Demo nutzt Standardmaessig zfork2_CompileBankV1()
 *   (ohne Embedding); zum Testen: zfork2_CompileBankV1Embedded() stattdessen
 *   aufrufen.
 *
 * Sound-Cache:
 *   PreDecoded-Sounds laufen ueber einen prozessweiten LRU-Cache
 *   (zfork2_SetSoundCacheBudget / zfork2_GetSoundCacheStats): jede Datei
 *   wird nur beim ersten Laden dekodiert; ein erneutes Laden desselben
 *   Pfads (z.B. Level-Reload, oder zwei Banks mit demselben UI-Sound)
 *   gibt sofort den schon dekodierten Buffer zurueck. Budget 0 (Default)
 *   = dynamisch/unbegrenzt, kein manuelles Sizing noetig.
 *
 * Gruppen-Effekte (Echo/Reverb) — jetzt per Bank-Datei gesteuert:
 *   soundbank_v1.txt enthaelt "@echo;ui;..." und "@reverb;music;...".
 *   zfork2_LoadBankV1() installiert diese automatisch beim Laden -- kein
 *   Code noetig, um sie einzuschalten. Effekte haengen an der GRUPPE (Bus),
 *   nicht am einzelnen Sound: jede Voice, die auf diese Gruppe spielt,
 *   laeuft automatisch mit durch, und der Effekt wird nur einmal pro
 *   Mix-Block fuer die ganze Gruppe berechnet (nicht pro Sound) -- deshalb
 *   ist das guenstig genug fuers Echtzeit-Budget (kMixFrames). Ein
 *   Pro-Sound-Effekt waere pro *spielender* Instanz eine eigene Delay-Line
 *   und damit teurer; wer mehrere Sounds gleich behandeln will, routet sie
 *   auf dieselbe Gruppe (wie ui_click/button_on/... schon auf "ui").
 *   Diese Demo setzt den Zustand beim Start bewusst zurueck (aus) und
 *   steuert Echo/Reverb ausschliesslich ueber die Tasten 'E'/'V' zur
 *   Laufzeit (siehe zfork2_SetGroupEcho/SetGroupReverb/ClearGroupEffect) --
 *   damit stimmt die Anzeige immer mit dem echten Zustand ueberein, egal
 *   ob die geladene Bank eigene @echo/@reverb-Direktiven mitbringt oder
 *   nicht (z.B. eine von zfork2_bank_builder generierte Bank hat keine).
 */

#define NOMINMAX
#define WIN32_LEAN_AND_MEAN
#include <libzfork/libzfork2.h>
#include <windows.h>
#include <conio.h>
#include <cstdio>
#include <deque>
#include <filesystem>
#include <string>
#include <vector>

namespace {

constexpr size_t kMaxLogLines = 8;

struct DemoState {
    std::deque<std::string> log;
    bool                     dirty = true;
};

void PushLog(DemoState& st, std::string line) {
    st.log.push_back(std::move(line));
    while (st.log.size() > kMaxLogLines) st.log.pop_front();
    st.dirty = true;
}

void OnEvent(int type, ZF2_VOICE voice, uint32_t p1, float p2, void* userData) {
    auto* st = static_cast<DemoState*>(userData);
    char  buf[128];
    switch (type) {
    case ZF2_EVENT_VOICE_START:
        std::snprintf(buf, sizeof(buf), "[event] start    voice=%u", voice);
        break;
    case ZF2_EVENT_VOICE_FINISHED:
        std::snprintf(buf, sizeof(buf), "[event] finished voice=%u", voice);
        break;
    case ZF2_EVENT_POSITION_CROSSED:
        std::snprintf(buf, sizeof(buf), "[event] marker   voice=%u marker=%u sec=%.3f", voice, p1, p2);
        break;
    default:
        return;
    }
    PushLog(*st, buf);
}

// Clears the console without spawning a process (unlike system("cls")) so
// redraws stay cheap enough to do on every state change.
void ClearScreen() {
    HANDLE hOut = GetStdHandle(STD_OUTPUT_HANDLE);
    CONSOLE_SCREEN_BUFFER_INFO csbi;
    if (hOut == INVALID_HANDLE_VALUE || !GetConsoleScreenBufferInfo(hOut, &csbi)) {
        std::system("cls");
        return;
    }
    const DWORD cellCount = static_cast<DWORD>(csbi.dwSize.X) * static_cast<DWORD>(csbi.dwSize.Y);
    const COORD home{ 0, 0 };
    DWORD written = 0;
    FillConsoleOutputCharacter(hOut, ' ', cellCount, home, &written);
    FillConsoleOutputAttribute(hOut, csbi.wAttributes, cellCount, home, &written);
    SetConsoleCursorPosition(hOut, home);
}

} // namespace

int main(int argc, char* argv[]) {
    std::setvbuf(stdout, nullptr, _IONBF, 0); // flush immediately when stdout is redirected/piped
    std::filesystem::path bankPath;
    if (argc >= 2) {
        bankPath = std::filesystem::path(argv[1]);
    } else {
        // Prefer the pre-compiled binary bank — no parsing/compiling at
        // startup, just a straight binary load. The .txt is only the
        // editable source; candidates are tried in this order so a binary
        // bank always wins when both exist next to each other.
        const std::filesystem::path candidates[] = {
            "samples/soundbank_v1.bank",           // when started from dist/examples
            "examples/samples/soundbank_v1.bank",  // when started from repo root
            "samples/soundbank_v1.txt",
            "examples/samples/soundbank_v1.txt"
        };
        for (const auto& c : candidates) {
            if (std::filesystem::exists(c)) {
                bankPath = c;
                break;
            }
        }
        if (bankPath.empty()) bankPath = candidates[0];
    }

    // If we were pointed at (or fell back to) the text source, compile it to
    // the binary "ZFBK" format and load that instead — but only when the
    // .bank is missing or older than the .txt, so re-runs after the first
    // one skip the compile step entirely (fast path: straight binary load).
    std::string compileNote;
    if (bankPath.extension() == ".txt") {
        std::filesystem::path binPath = bankPath;
        binPath.replace_extension(".bank");

        bool needsCompile = true;
        std::error_code ec;
        if (std::filesystem::exists(binPath, ec)) {
            auto txtTime = std::filesystem::last_write_time(bankPath, ec);
            auto binTime = std::filesystem::last_write_time(binPath, ec);
            if (!ec && binTime >= txtTime) needsCompile = false;
        }

        if (needsCompile) {
            if (zfork2_CompileBankV1(bankPath.wstring().c_str(), binPath.wstring().c_str())) {
                compileNote = "Bank kompiliert: " + bankPath.string() + " -> " + binPath.string();
                bankPath = binPath;
            } else {
                compileNote = "[warn] Kompilieren nach Binaerformat fehlgeschlagen, verwende Text-Bank.";
            }
        } else {
            bankPath = binPath;
        }
    }

    ZF2_CONTEXT ctx = zfork2_CreateContext();
    if (!ctx) {
        std::fprintf(stderr, "FEHLER: CreateContext fehlgeschlagen\n");
        return 1;
    }

    DemoState state;
    zfork2_SetCallback(ctx, OnEvent, &state);
    if (!zfork2_Start(ctx)) {
        std::fprintf(stderr, "FEHLER: Start fehlgeschlagen (Soundkarte verfügbar?)\n");
        zfork2_DestroyContext(ctx);
        return 1;
    }

    ZF2_BANK bank = zfork2_LoadBankV1(ctx, bankPath.wstring().c_str());
    if (!bank) {
        std::fprintf(stderr, "FEHLER: Bank-Datei konnte nicht geöffnet werden.\n");
        std::fprintf(stderr, "  Pfad: %s\n", bankPath.string().c_str());
        std::fprintf(stderr, "  Prüfe ob die Datei existiert.\n");
        zfork2_Stop(ctx);
        zfork2_DestroyContext(ctx);
        return 1;
    }

    if (zfork2_GetBankEntryCount(bank) == 0) {
        std::printf("KEINE Events geladen — nichts zum Abspielen. Pfad: %s\n", bankPath.string().c_str());
        zfork2_UnloadBankV1(bank);
        zfork2_Stop(ctx);
        zfork2_DestroyContext(ctx);
        return 1;
    }

    ZF2_GROUP uiGroup    = zfork2_GetGroup(ctx, "ui");
    ZF2_GROUP musicGroup = zfork2_GetGroup(ctx, "music");
    // Both groups always exist (zfork2_CreateContext pre-registers "master",
    // "music", "sfx", "ui" regardless of which bank gets loaded), so these
    // toggles are always valid even for a bank that never mentions them.
    // Force a known starting state (off) so the displayed toggle always
    // matches reality — some banks (e.g. the hand-authored sample) install
    // @echo/@reverb directives automatically on load; this menu takes
    // explicit manual control over that instead of trying to reflect it.
    zfork2_ClearGroupEffect(ctx, uiGroup, ZF2_EFFECT_ECHO);
    zfork2_ClearGroupEffect(ctx, musicGroup, ZF2_EFFECT_REVERB);
    bool echoOn   = false;
    bool reverbOn = false;

    // Dynamically enumerate whatever events this bank actually contains —
    // no assumption about specific ids like "ui_click" (those only exist in
    // the hand-authored sample bank; a bank_builder-generated one has
    // completely different, file-name-derived ids).
    const uint32_t eventCount = zfork2_GetBankEntryCount(bank);
    std::vector<std::string> eventNames;
    eventNames.reserve(eventCount);
    for (uint32_t i = 0; i < eventCount; ++i) {
        char name[256] = {};
        if (zfork2_GetBankEventName(bank, i, name, sizeof(name))) eventNames.emplace_back(name);
    }

    // Key pool for the dynamic menu — 'e', 'q', 'v' are reserved (echo
    // toggle, quit, reverb toggle). Caps how many events get a hotkey; a
    // bank with more entries than this just shows the first N (a real game
    // wouldn't drive playback from a keyboard menu at all — see the notes
    // in the class comment of soundbank_v1.h for the actual API to call
    // from game code: zfork2_PlayEventV1 with any event id string).
    const std::string keyPool = "123456789abcdfghijklmnoprstuwxyz";
    const size_t shownCount = std::min(eventNames.size(), keyPool.size());

    auto tryPlay = [&](const std::string& evId) {
        ZF2_VOICE v = zfork2_PlayEventV1(ctx, bank, evId.c_str());
        if (v == ZF2_INVALID_VOICE)
            PushLog(state, "[warn] Event '" + evId + "' konnte nicht gespielt werden");
        return v;
    };

    auto redraw = [&] {
        ClearScreen();
        std::printf("=== libZFork2 Soundbank V1 Demo ===\n\n");
        if (!compileNote.empty()) std::printf("%s\n", compileNote.c_str());

        std::printf("Bank:     %s\n", bankPath.string().c_str());
        std::printf("Geladen:  %u Event(s), %u uebersprungen\n",
                    zfork2_GetBankEntryCount(bank), zfork2_GetBankSkippedCount(bank));

        uint64_t cacheBytes = 0;
        uint32_t cacheCount = 0;
        zfork2_GetSoundCacheStats(&cacheBytes, &cacheCount);
        std::printf("Sound-Cache: %u Eintrag/Eintraege, %.1f KiB (Budget: %s)\n",
                    cacheCount, cacheBytes / 1024.0,
                    zfork2_GetSoundCacheBudget() == 0 ? "dynamisch" : "begrenzt");

        char     backendName[64] = {};
        uint32_t periodFrames    = 0;
        if (zfork2_GetOutputBackendInfo(ctx, backendName, sizeof(backendName), &periodFrames))
            std::printf("Audio-Backend: %s\n", backendName);

        std::printf("\n--- Sounds in dieser Bank (%zu/%zu angezeigt) --------------\n",
                    shownCount, eventNames.size());
        for (size_t i = 0; i < shownCount; ++i)
            std::printf("  %c = %s\n", keyPool[i], eventNames[i].c_str());
        if (eventNames.size() > shownCount)
            std::printf("  ... (%zu weitere, keine Taste mehr frei)\n", eventNames.size() - shownCount);

        std::printf("\n--- Steuerung ------------------------------------------\n");
        std::printf("E = Echo   [%s]   (Gruppe 'ui')\n",    echoOn   ? "AN " : "AUS");
        std::printf("V = Reverb [%s]   (Gruppe 'music')\n", reverbOn ? "AN " : "AUS");
        std::printf("Q/Esc = Ende\n");
        std::printf("----------------------------------------------------------\n\n");

        std::printf("Ereignisse:\n");
        for (const auto& line : state.log) std::printf("  %s\n", line.c_str());
        for (size_t i = state.log.size(); i < kMaxLogLines; ++i) std::printf("\n");

        state.dirty = false;
    };

    redraw();

    while (true) {
        zfork2_Update(ctx);

        if (_kbhit()) {
            int ch = _getch();
            bool handled = true;
            auto keyIdx = keyPool.find(static_cast<char>(std::tolower(ch)));
            if (keyIdx != std::string::npos && keyIdx < shownCount) {
                tryPlay(eventNames[keyIdx]);
            } else if (ch == 'e' || ch == 'E') {
                echoOn = !echoOn;
                if (echoOn) {
                    zfork2_EchoParams echo{ 180, 100, 45, 180, 100, 45 };
                    zfork2_SetGroupEcho(ctx, uiGroup, &echo);
                } else {
                    zfork2_ClearGroupEffect(ctx, uiGroup, ZF2_EFFECT_ECHO);
                }
                state.dirty = true;
            } else if (ch == 'v' || ch == 'V') {
                reverbOn = !reverbOn;
                if (reverbOn) {
                    zfork2_ReverbParams reverb{ 0.65f, 0.5f, 0.35f, 0.7f };
                    zfork2_SetGroupReverb(ctx, musicGroup, &reverb);
                } else {
                    zfork2_ClearGroupEffect(ctx, musicGroup, ZF2_EFFECT_REVERB);
                }
                state.dirty = true;
            } else if (ch == 'q' || ch == 'Q' || ch == 27) {
                break;
            } else {
                handled = false;
            }
            if (handled) redraw();
        } else if (state.dirty) {
            redraw();
        }

        Sleep(16);
    }

    zfork2_UnloadBankV1(bank);
    zfork2_Stop(ctx);
    zfork2_DestroyContext(ctx);
    std::printf("Fertig.\n");
    return 0;
}
